mapper.select:
SELECT hp.id, hp.name, hp.cover, hp.description AS summary, hp.category_id AS categoryId, COALESCE(c.name, hp.category) AS category, hp.level_code AS levelCode, COALESCE(hl.name, hp.level) AS level, hp.region_code AS regionCode, hp.region, hp.official_code AS officialCode, hp.recognition_authority AS recognitionAuthority, hp.recognition_batch AS recognitionBatch, hp.recognized_at AS recognizedAt FROM heritage_project hp LEFT JOIN category c ON c.id = hp.category_id AND c.biz_type = 'HERITAGE' LEFT JOIN heritage_level hl ON hl.code = hp.level_code AND hl.status = 1 WHERE hp.status = 1 AND hp.is_recommend = 1
AND hp.region_code = #{regionCode}
ORDER BY hp.recommend_sort ASC, hp.sort DESC, hp.id DESC LIMIT #{limit}

SELECT ranked.id, ranked.title, ranked.cover, ranked.summary, ranked.inheritorId, ranked.inheritorName, ranked.heritageProjectId, ranked.categoryId, ranked.category, ranked.serviceMode, ranked.price, ranked.durationMinutes, ranked.cityCode, ranked.location, ranked.nextSessionId, ranked.nextStartTime, ranked.nextEndTime, ranked.remaining FROM ( SELECT c.id, c.title, c.cover, c.summary, c.inheritor_id AS inheritorId, i.display_name AS inheritorName, c.heritage_project_id AS heritageProjectId, c.category_id AS categoryId, category.name AS category, c.service_mode AS serviceMode, c.price, c.duration_minutes AS durationMinutes, COALESCE(cs.city_code, c.city_code) AS cityCode, COALESCE(cs.location, c.location) AS location, cs.id AS nextSessionId, cs.start_time AS nextStartTime, cs.end_time AS nextEndTime, GREATEST(cs.capacity - cs.booked_count, 0) AS remaining, c.recommend_sort AS recommendSort, ROW_NUMBER() OVER ( PARTITION BY c.id ORDER BY cs.start_time ASC, cs.id ASC ) AS rowNumber FROM course c JOIN course_session cs ON cs.course_id = c.id AND cs.status = 1 AND cs.start_time >= #{weekStart} AND cs.start_time < #{weekEnd} LEFT JOIN inheritor i ON i.id = c.inheritor_id LEFT JOIN category ON category.id = c.category_id WHERE c.audit_status = 1 AND c.publish_status = 1 AND c.is_recommend = 1
AND COALESCE(cs.city_code, c.city_code) = #{cityCode}
) ranked WHERE ranked.rowNumber = 1 ORDER BY ranked.recommendSort ASC, ranked.nextStartTime ASC, ranked.id DESC LIMIT #{limit}

SELECT id, name, cover, description AS summary, city_code AS cityCode, COALESCE(address_detail, location) AS location, start_time AS startTime, end_time AS endTime, organizer_name AS organizerName, limit_count AS limitCount, signup_count AS signupCount, GREATEST(limit_count - signup_count, 0) AS remaining FROM activity WHERE status = 1 AND is_recommend = 1 AND COALESCE(end_time, start_time) >= #{now}
AND city_code = #{cityCode}
ORDER BY recommend_sort ASC, start_time ASC, id DESC LIMIT #{limit}
